def getSuitVitals(name, level = -1):
    data = SuitAttributes[name]
    if level == -1:
        level = pickFromFreqList(data['freq'])
    dict = {}
    dict['level'] = getActualFromRelativeLevel(name, level)
    if dict['level'] == 11:
        level = 0
    dict['hp'] = data['hp'][level]
    dict['def'] = data['def'][level]
    attacks = data['attacks']
    cheats = data['cheats']
    alist = []
    clist = []
    for a in attacks:
        adict = {}
        if isinstance(a, SuitAttack):
            name = a.name
            adict['name'] = name
            adict['animName'] = SuitAttacks[name][0]
            # Try and get the attack data from the appropriate index.
            try:
                adict['hp'] = a.hp[level]
            except IndexError:
                # Chances are we went over.  Let's do overleveling logic!
                adict['hp'] = a.hp[len(a.hp) - 1] + (level - (len(a.hp) - 1))
            # Same thing for the below, except we're just using the final index rather than adding anything to the final index.
            try:
                adict['acc'] = a.acc[level]
            except IndexError:
                adict['acc'] = a.acc[len(a.acc) - 1]
            try:
                adict['freq'] = a.freq[level]
            except IndexError:
                adict['freq'] = a.freq[len(a.freq) - 1]
            adict['group'] = a.groupStatus
        else:
            name = a[0]
            adict['name'] = name
            adict['animName'] = SuitAttacks[name][0]
            # Try and get the attack data from the appropriate index.
            try:
                adict['hp'] = a[1][level]
            except IndexError:
                # Chances are we went over.  Let's do overleveling logic!
                adict['hp'] = a[1][len(a[1]) - 1] + (level - (len(a[1]) - 1))
            # Same thing for the below, except we're just using the final index rather than adding anything to the final index.
            try:
                adict['acc'] = a[2][level]
            except IndexError:
                adict['acc'] = a[2][len(a[2]) - 1]
            try:
                adict['freq'] = a[3][level]
            except IndexError:
                adict['freq'] = a[3][len(a[3]) - 1]
            # Attack tuples have four indices.  This will check to see if there is a fifth one, which I would like to use to make single-target attacks able to be used as group, provided we have a method for its use.
            if len(a) > 4:
                adict['group'] = a[4]
            else:
                # Use the default targeting in SuitAttacks.
                adict['group'] = SuitAttacks[name][1]
        alist.append(adict)
    for c in cheats:
        cdict = {}
        name = c[0]
        cdict['name'] = name
        cdict['animName'] = SuitCheats[name][0]
        cdict['hp'] = c[1][level]
        cdict['acc'] = c[2][level]
        cdict['freq'] = c[3][level]
        cdict['group'] = SuitCheats[name][1]
        clist.append(cdict)

    dict['attacks'] = alist
    dict['cheats'] = clist
    return dict


def calculateDefense(suitLevel, levelOffset, boost=0):
    defense = int(suitLevel * 5 + (levelOffset * 5))
    if defense > 55:
        defense = 55
    elif defense <= 0:
        defense = 2
    defense += boost
    return defense

def getAttackIndex(attackName, suitName):
    '''
    For convenience, until I find a way to use attack names instead of indexes for SUIT_ATK_COL, grab the index based on the attack name.
    attackName: The attack (e.g. 'ClipOnTie', 'SnapWet', etc.).
    '''
    attacks = SuitAttributes[suitName]['attacks']
    for i in xrange(len(attacks)):
        attack = attacks[i]
        if isinstance(attack, SuitAttack):
            if attack.name == attackName:
                return i
        else:
            if attack[0] == attackName:
                return i

    # No attack found.
    notify.warning('Did not find attack %s for suitName %s' % (attackName, suitName))
    return -1

