def pickSuitAttack(attacks, suitLevel):
    configAttackName = simbase.config.GetString('attack-type', 'random')
    if configAttackName == 'random':
        pass # Proceed downward to calculate and return attackNum
    elif configAttackName == 'sequence':
        for i in xrange(len(attacks)):
            if  attacks[i] not in debugAttackSequence:
                debugAttackSequence[attacks[i]] = 1
                if isinstance(attacks[i], SuitAttack):
                    return attacks[i].name
                else:
                    return attacks[i][0]

    else:
        # Feasibly, one could just do a "return configAttackName", but with the new system, this will not account for whether or not the Cog has the attack.
        for i in xrange(len(attacks)):
            if isinstance(attacks[i], SuitAttack):
                if attacks[i].name == configAttackName:
                    return attacks[i].name
            else:
                if attacks[i][0] == configAttackName:
                    return attacks[i][0]

    attackNum = None
    randNum = random.randint(0, 99)
    notify.debug('pickSuitAttack: rolled %d' % randNum)
    count = 0
    index = 0
    total = 0
    for c in attacks:
        if isinstance(c, SuitAttack):
            total = total + c.freq[suitLevel]
        else:
            total = total + c[3][suitLevel]

    for c in attacks:
        if isinstance(c, SuitAttack):
            count = count + c.freq[suitLevel]
        else:
            count = count + c[3][suitLevel]
        if randNum < count:
            attackNum = index
            notify.debug('picking attack %d' % attackNum)
            break
        index = index + 1
    attack = attacks[attackNum]
    if isinstance(attack, SuitAttack):
        return attacks[attackNum].name
    else:
        return attacks[attackNum][0]


def pickSuitCheat(cheats, suitLevel):
    cheatNum = None
    randNum = random.randint(0, 99)
    notify.debug('pickSuitAttack: rolled %d' % randNum)
    count = 0
    index = 0
    total = 0
    for c in cheats:
        total = total + c[3][suitLevel]

    for c in cheats:
        count = count + c[3][suitLevel]
        if randNum < count:
            attackNum = index
            notify.debug('picking attack %d' % attackNum)
            break
        index = index + 1

    configAttackName = simbase.config.GetString('attack-type', 'random')
    if configAttackName == 'random':
        return attackNum
    elif configAttackName == 'sequence':
        for i in xrange(len(attacks)):
            if cheats[i] not in debugAttackSequence:
                debugAttackSequence[cheats[i]] = 1
                return i

        return cheatNum
    else:
        for i in xrange(len(cheats)):
            if cheats[i][0] == configAttackName:
                return i

        return cheatNum
    return


def findAttack(suitName, attackName):
    for attack in SuitAttributes[suitName]['attacks']:
        if isinstance(attack, SuitAttack):
            if attack.name == attackName:
                return attack
        else:
            if attack[0] == attackName:
                return attack

    notify.error('We ran into an issue finding the %(attackName)s attack for %(suitName)s. Does %(suitName)s have %(attackName)s?' % {'attackName': attackName,
                                                                                                                                      'suitName': suitName})

def getSuitCheat(suitName, suitLevel, cheatNum = -1):
    cheatChoices = SuitAttributes[suitName]['cheats']
    if cheatNum == -1:
        notify.debug('getSuitAttack: picking attacking for %s' % suitName)
        cheatNum = pickSuitCheat(cheatChoices, suitLevel)
    cheat = cheatChoices[cheatNum]
    cdict = {}
    cdict['suitName'] = suitName
    name = attack[0]
    cdict['name'] = name
    cdict['id'] = SuitAttacks.keys().index(name)
    cdict['animName'] = SuitAttacks[name][0]
    cdict['hp'] = cheat[1][suitLevel]
    cdict['acc'] = cheat[2][suitLevel]
    cdict['freq'] = cheat[3][suitLevel]
    cdict['group'] = SuitAttacks[name][1]
    return cdict


def getSuitAttack(suitName, suitLevel, attackName = ''):
    attackChoices = SuitAttributes[suitName]['attacks']
    if attackName == '':
        notify.debug('getSuitAttack: picking attacking for %s' % suitName)
        attackName = pickSuitAttack(attackChoices, suitLevel)
    attack = findAttack(suitName, attackName)
    adict = {}
    adict['suitName'] = suitName
    if isinstance(attack, SuitAttack):
        name = attack.name
        adict['name'] = name
        adict['animName'] = SuitAttacks[name][0]
        try:
            adict['hp'] = attack.hp[suitLevel]
        except IndexError:
            adict['hp'] = attack.hp[len(attack.hp) - 1] + (suitLevel - (len(attack.hp) - 1))
        try:
            adict['acc'] = attack.acc[suitLevel]
        except IndexError:
            adict['acc'] = attack.acc[len(attack.acc) - 1]
        try:
            adict['freq'] = attack.freq[suitLevel]
        except IndexError:
            adict['freq'] = attack.freq[len(attack.freq) - 1]
        if attack.groupStatus is None:
            attack.groupStatus = SuitAttacks[name][1]
        adict['group'] = attack.groupStatus
    else:
        name = attack[0]
        adict['name'] = name
        adict['animName'] = SuitAttacks[name][0]
        try:
            adict['hp'] = attack[1][suitLevel]
        except IndexError:
            adict['hp'] = attack[1][len(attack[1]) - 1] + (suitLevel - (len(attack[1]) - 1))
        try:
            adict['acc'] = attack[2][suitLevel]
        except IndexError:
            adict['acc'] = attack[2][len(attack[2]) - 1]
        try:
            adict['freq'] = attack[3][suitLevel]
        except IndexError:
            adict['freq'] = attack[3][len(attack[3]) - 1]
        if len(attack) > 4:
            adict['group'] = attack[4]
        else:
            adict['group'] = SuitAttacks[name][1]
    return adict

